<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import * as echarts from './charts';import {formatMetricValue} from './metric-format';
const props=defineProps({points:Array,metric:String});const root=ref();let c,ro;
function render(){if(!c)return;c.setOption({animationDuration:300,grid:{left:55,right:25,top:30,bottom:38},tooltip:{trigger:'axis',valueFormatter:value=>formatMetricValue(props.metric,value)},xAxis:{type:'category',data:(props.points||[]).map(p=>new Date(p.ts).toLocaleString('zh-CN',{hour:'2-digit',minute:'2-digit'})),axisLine:{lineStyle:{color:'#dbe4df'}},axisLabel:{color:'#7b8885',hideOverlap:true}},yAxis:{type:'value',scale:true,splitLine:{lineStyle:{color:'#edf0ec'}},axisLabel:{color:'#7b8885',formatter:value=>formatMetricValue(props.metric,value)}},series:[{type:'line',smooth:true,symbolSize:5,name:props.metric,data:(props.points||[]).map(p=>p.values[props.metric]),lineStyle:{color:'#318064',width:2.5},itemStyle:{color:'#318064'},areaStyle:{color:'#e6f2ea',opacity:.6}}]})}
onMounted(()=>{c=echarts.init(root.value);ro=new ResizeObserver(()=>c.resize());ro.observe(root.value);render()});watch(()=>[props.points,props.metric],render,{deep:true});onBeforeUnmount(()=>{ro?.disconnect();c?.dispose()});defineExpose({image:()=>c?.getDataURL({pixelRatio:2,backgroundColor:'#fff'})});
</script><template><div class="trend" ref="root" role="img" aria-label="环境参数历史变化曲线"/></template>
